/* =============================================================================
   EarningAuditDataCleanUp.sql
   ============================================================================= */

SET NOCOUNT ON;

-------------------------------------------------------------------------------
-- Script set up
-------------------------------------------------------------------------------
DECLARE @BatchSize         INT = 1;
DECLARE @MaxRuntimeMinutes INT = 360;   -- Currently set to 6 hours but override if needed

DECLARE @CurrentCollectionPeriod  VARCHAR(10) = '@{if(empty(pipeline().parameters.CurrentCollectionPeriod), string(activity('GetCurrentPeriod').output.firstRow.CurrentCollectionPeriod), pipeline().parameters.CurrentCollectionPeriod)}';
DECLARE @CurrentAcademicYear      VARCHAR(10) = '@{if(empty(pipeline().parameters.CurrentAcademicYear), string(activity('GetCurrentPeriod').output.firstRow.CurrentAcademicYear), pipeline().parameters.CurrentAcademicYear)}';
DECLARE @PreviousCollectionPeriod VARCHAR(10) = NULLIF('@{if(empty(pipeline().parameters.PreviousCollectionPeriod), string(activity('GetCurrentPeriod').output.firstRow.PreviousCollectionPeriod), pipeline().parameters.PreviousCollectionPeriod)}', '');
DECLARE @PreviousAcademicYear     VARCHAR(10) = NULLIF('@{if(empty(pipeline().parameters.PreviousAcademicYear), string(activity('GetCurrentPeriod').output.firstRow.PreviousAcademicYear), pipeline().parameters.PreviousAcademicYear)}', '');

IF NULLIF(LTRIM(RTRIM(@CurrentCollectionPeriod)), '') IS NULL
   OR NULLIF(LTRIM(RTRIM(@CurrentAcademicYear)), '') IS NULL
BEGIN
    RAISERROR('Set @CurrentCollectionPeriod and @CurrentAcademicYear before running this script.', 16, 1);
    RETURN;
END

DECLARE @RunId    UNIQUEIDENTIFIER = NEWID();
DECLARE @RunStart DATETIME2        = SYSUTCDATETIME();
DECLARE @StopBy   DATETIME2        = DATEADD(MINUTE, @MaxRuntimeMinutes, @RunStart);

PRINT CONCAT('EarningAuditDataCleanUp run ', @RunId, ' starting at ', CONVERT(varchar(30), @RunStart, 126));
PRINT CONCAT('Period scope: current [', @CurrentCollectionPeriod, '/', @CurrentAcademicYear, ']',
             ' + previous [', ISNULL(@PreviousCollectionPeriod, '-'), '/', ISNULL(@PreviousAcademicYear, '-'), ']');

-------------------------------------------------------------------------------
-- IDENTIFY ELIGIBLE JOBS
-------------------------------------------------------------------------------
IF OBJECT_ID('tempdb..#EligibleJobs') IS NOT NULL DROP TABLE #EligibleJobs;

SELECT distinct JobId INTO #EligibleJobs FROM Payments2.EarningEvent
WHERE (CollectionPeriod = @CurrentCollectionPeriod AND AcademicYear = @CurrentAcademicYear)
   OR (CollectionPeriod = @PreviousCollectionPeriod AND AcademicYear = @PreviousAcademicYear);

-- keep all successful jobs
DELETE FROM #EligibleJobs WHERE JobId IN (SELECT DcJobId FROM Payments2.LatestSuccessfulJobs);

-- keep all in progress, timed-out and failed on DC jobs
DELETE FROM #EligibleJobs WHERE JobId IN (SELECT DcJobId FROM Payments2.Job WHERE [Status] IN (1, 4, 5));

-- keep any jobs completed our side but DC status is unknown
DELETE FROM #EligibleJobs WHERE JobId IN (SELECT DcJobId FROM Payments2.Job WHERE [Status] IN (2, 3) AND DCJobSucceeded IS NULL);

-- exclude EAP GSO jobs
DELETE FROM #EligibleJobs WHERE JobId = 0;

-------------------------------------------------------------------------------
-- PROCESS EACH ELIGIBLE JOB
-------------------------------------------------------------------------------
DECLARE @JobId         BIGINT;
DECLARE @Count         INT;
DECLARE @BatchCount    INT = 0;
DECLARE @SuccessCount  INT = 0;
DECLARE @FailureCount  INT = 0;

DECLARE JobCursor CURSOR LOCAL FAST_FORWARD FOR
    SELECT JobId FROM #EligibleJobs ORDER BY JobId;

OPEN JobCursor;
FETCH NEXT FROM JobCursor INTO @JobId;

WHILE @@FETCH_STATUS = 0
BEGIN
    IF SYSUTCDATETIME() >= @StopBy
    BEGIN
        PRINT CONCAT('Max runtime of ', @MaxRuntimeMinutes, ' minutes reached - stopping. Remaining JobIds will be picked up on the next run.');
        BREAK;
    END

    BEGIN TRY
        DELETE Payments2.EarningEventPeriod
        FROM Payments2.EarningEventPeriod AS EEP
            INNER JOIN Payments2.EarningEvent AS EE ON EEP.EarningEventId = EE.EventId
        WHERE EE.JobId = @JobId;
        SET @Count = @@ROWCOUNT;
        PRINT CONCAT('DELETED ', @Count, ' earningEventPeriods for JobId ', @JobId);

        DELETE Payments2.EarningEventPriceEpisode
        FROM Payments2.EarningEventPriceEpisode AS EEPE
            INNER JOIN Payments2.EarningEvent AS EE ON EEPE.EarningEventId = EE.EventId
        WHERE EE.JobId = @JobId;
        SET @Count = @@ROWCOUNT;
        PRINT CONCAT('DELETED ', @Count, ' earningEventPriceEpisodes for JobId ', @JobId);

        DELETE FROM Payments2.EarningEvent WHERE JobId = @JobId;
        SET @Count = @@ROWCOUNT;
        PRINT CONCAT('DELETED ', @Count, ' EarningEvents for JobId ', @JobId);

        SET @SuccessCount += 1;
    END TRY
    BEGIN CATCH
        SET @FailureCount += 1;
        PRINT CONCAT('Error Deleting Audit Data for JobId ', @JobId, ', internal Exception ', ERROR_MESSAGE());
    END CATCH

    SET @BatchCount += 1;

    IF @BatchCount % @BatchSize = 0
        PRINT CONCAT(CONVERT(varchar(30), SYSUTCDATETIME(), 126), ' - processed ', @BatchCount, ' JobId(s) so far this run.');

    FETCH NEXT FROM JobCursor INTO @JobId;
END

CLOSE JobCursor;
DEALLOCATE JobCursor;

-------------------------------------------------------------------------------
-- RUN SUMMARY
-------------------------------------------------------------------------------
DECLARE @RunEnd DATETIME2 = SYSUTCDATETIME();

PRINT CONCAT('EarningAuditDataCleanUp run ', @RunId, ' finished at ', CONVERT(varchar(30), @RunEnd, 126),
             ' (elapsed ', DATEDIFF(SECOND, @RunStart, @RunEnd), 's). ',
             @SuccessCount, ' JobId(s) processed, ', @FailureCount, ' failed.');

